fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn dims() -> i32 { (480 << 16) | 270 }

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let gy: i32 = h - 40;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(2, 0);
        host::display::state_set(3, w);
        host::display::state_set(4, 1);
        host::display::state_set(5, 0);
        host::display::state_set(6, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(7) == 0;
    host::display::state_set(7, down);
    let score: i32 = host::display::state_get(5);
    if host::display::state_get(6) == 1 {
        host::display::clear(0x101010);
        host::display::draw_string(150, 80, "TRIPPED", 0xff4040, 4);
        host::display::draw_string(120, 140, "CLEARED", 0x808080, 2);
        host::display::draw_number(260, 134, score, 0xffffff, 3);
        host::display::draw_string(120, 174, "BEST", 0x808080, 2);
        host::display::draw_number(260, 168, host::display::state_get(8), 0x00ff88, 3);
        host::display::draw_string(140, 220, "TAP TO RUN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut dy: i32 = host::display::state_get(1);
        let mut vy: i32 = host::display::state_get(2);
        if tap && dy == 0 { vy = 44; }
        dy = dy + vy;
        vy = vy - 4;
        if dy <= 0 { dy = 0; vy = 0; }
        host::display::state_set(1, dy);
        host::display::state_set(2, vy);
        let mut ox: i32 = host::display::state_get(3);
        let mut spd: i32 = 5 + score / 5;
        if spd > 9 { spd = 9; }
        ox = ox - spd;
        if ox < -24 {
            let rnd: i32 = host::display::state_get(4) + 1;
            host::display::state_set(4, rnd);
            ox = w + hash(rnd) % 140;
            host::display::state_set(5, score + 1);
        }
        host::display::state_set(3, ox);
        let dtop: i32 = gy - 30 - dy / 8;
        if 50 + 26 > ox && 50 < ox + 20 && dtop + 30 > gy - 24 {
            host::display::state_set(6, 1);
            if score > host::display::state_get(8) {
                host::display::state_set(8, score);
            }
        }
        host::display::clear(0xf0f0e8);
        host::display::fill_rect(0, gy, w, 2, 0x202020);
        let mut mx: i32 = 0 - (t * 2) % 60;
        while mx < w {
            host::display::fill_rect(mx, gy + 10, 20, 2, 0xb0b0a8);
            mx = mx + 60;
        }
        host::display::fill_rect(50, dtop, 26, 30, 0x303030);
        host::display::fill_rect(68, dtop + 4, 6, 6, 0xf0f0e8);
        host::display::fill_rect(ox, gy - 24, 20, 24, 0x117733);
        host::display::fill_rect(ox - 6, gy - 16, 6, 10, 0x117733);
        host::display::fill_rect(ox + 20, gy - 18, 6, 10, 0x117733);
        host::display::draw_number(w - 90, 10, score, 0x202020, 3);
    }
    host::display::present();
}
